	@Operation(summary = "", description = "Method fetch all delivered shipment by search form.")
	@PostMapping("/search-received")
	@PreAuthorize("@authz.hasAnyOfAllowedRole(authentication,'ADMIN','BRANCH','CIB')")
	public ResponseEntity<List<rs.unicredit.cardlifecycle.model.Perso>> searchReceived(@RequestBody PersoSearchForm persoSearchForm, HttpServletRequest request, Authentication p){
		logger.info(request,OperationCategory.DATA_READ_MODIFY_DELETE, "Card recevied by search form: " + persoSearchForm.toString()); 
		List <String> inStatus = new ArrayList<String>();
		inStatus.add(RECEIVED);
		inStatus.add(SENT);
		inStatus.add(REJECT);
		inStatus.add(PRINTED);
		inStatus.add(REDIRECTED);
		inStatus.add(SURPLUS);
		inStatus.add(PREIMPORTED);
		persoSearchForm.setInStatus(inStatus);
		boolean hasNotificationAdmin = p.getAuthorities()
				.stream()
				.map(GrantedAuthority::getAuthority)
				.anyMatch(a -> a.contains("App-Notification-Admin"));
		if (hasNotificationAdmin) {
			persoSearchForm.setBranchRole(false);
		} else {
			persoSearchForm.setBranchRole(true);
		}
		return ResponseEntity.ok(persoService.getAllPersoBySearchForm(persoSearchForm));
		}

