    public List<Perso> getAllShipmentForMyBranch(String department) {
        logger.info("Fetching all shipments for branch: {}", department);
        List<Perso> listPerso = persoRepo.findByOBranchAndOStampaAndStatusAndBranchDeliveryIsNullOrderByODatumDesc(department,  CS.PRINTED.getId(), CS.SENT.getId());
