    private Boolean processShipment(ShipmentDTO shipmentDto, CS status,  String user, String department) {

        Optional<Perso> optionalPerso = persoRepo.findById(shipmentDto.getId());
        LocalDateTime currentDateTime = LocalDateTime.now();
        if (optionalPerso.isPresent()) {
            Perso p = optionalPerso.get();
           // logger.info("Processing Perso: {}", p);

            if (CS.SENT.getText().equalsIgnoreCase(status.getText())) {  /* Promena statusa na psolato  */
                logger.info("Processing Perso: Poslato");
                p.setStatus(CS.SENT.getId());
                if ("Manjak".equalsIgnoreCase(p.getBranchDelivery())) {
                    p.setBranchDelivery(null);
                }
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
            }
            if (CS.RECEIVED.getText().equalsIgnoreCase(status.getText())) {  /* Pri prijemu kartica azuriramo BranchDelivery  */
                logger.info("Processing Perso: Primljeno");
                p.setStatus(CS.RECEIVED.getId());
                p.setBranchDelivery(shipmentDto.getOBranch());
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
            }
            if (CS.SURPLUS_MANJAK.getText().equalsIgnoreCase(status.getText())) {  /* Pri manjku kartica azuriramo BranchDelivery na NULU  */
                p.setBranchDelivery(CS.SURPLUS_MANJAK.getText());
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
            }
            if (CS.SURPLUS.getText().equalsIgnoreCase(status.getText())) {
            	p.setStatus(CS.RECEIVED.getId());/* Pri visku kartica azuriramo BranchDelivery na trenutni branch usera  */
                p.setBranchDelivery(department);
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
            }
            if (CS.REDIRECTED.getText().equalsIgnoreCase(status.getText())) {  /* Pri redirekciji kartica azuriramo BranchDelivery na null  */
                p.setStatus(CS.SENT.getId());
                p.setBranchDelivery(null);
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
                p.setNotifSentFlag(0);
                p.setODatum(currentDateTime);
            }
            if (CS.SURPLUS_STORNO.getText().equalsIgnoreCase(status.getText())) {  /* Pri sorniranju kartica azuriramo BranchDelivery na null i bitnije status na 10 */
                logger.info("Processing Perso: Storno");
                p.setBranchDelivery(null);
                p.setStatus(CS.SURPLUS_STORNO.getId());
                p.setUpdatedBy(user);
                p.setUpdatedAt(currentDateTime);
            }
            if (CS.ACTIVATE.getText().equalsIgnoreCase(status.getText())) {  /* Pri aktiviranju kartica azuriramo BranchDelivery na null i bitnije status na 16 */
                logger.info("Processing Perso: Aktivacija");
                p.setStatus(CS.ACTIVATE.getId());
                if ("Manjak".equalsIgnoreCase(p.getBranchDelivery())) {
                    p.setBranchDelivery(null);
                }
                p.setUpdatedBy(user);

