import org.springframework.stereotype.Component;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

@Component
public class KeycloakService {

	private static final Logger logger = LoggerFactory.getLogger(KeycloakService.class);
	
	private static String REALM_ACCESS= "realm_access";
    private static String PUBLIC_KEY = "public_key";
    private static String ROLES = "roles";
    private static String OFFICE = "office";
	private static String USERNAME = "username";

	@Value("${spring.security.oauth2.resourceserver.jwt.issuer-uri}")
	private String issuerUri;

	public JwtDecoder getJwtDecoder() {
	    try {
	        HttpURLConnection connection = (HttpURLConnection) new URL(issuerUri).openConnection();
	        connection.setRequestMethod("GET");
	        connection.setRequestProperty("Accept", "application/json");

	        ObjectMapper objectMapper = new ObjectMapper();
	        JsonNode responseJson = objectMapper.readTree(connection.getInputStream());
	        String publicKeyPEM = responseJson.get(PUBLIC_KEY).asText();
	        
	        byte[] decodedKey = Base64.getDecoder().decode(publicKeyPEM.replaceAll("\\s+", ""));
	        X509EncodedKeySpec keySpec = new X509EncodedKeySpec(decodedKey);
	        RSAPublicKey publicKey = (RSAPublicKey) KeyFactory.getInstance("RSA").generatePublic(keySpec);

	        return NimbusJwtDecoder.withPublicKey(publicKey).build();
	    } catch (Exception e) {
	        throw new RuntimeException("Error configuring JWT public key for Keycloak", e);
	    }
	}

	public boolean validateJwtTokenWithRSA(String token) {
	    try {
	        JwtDecoder jwtDecoder = getJwtDecoder();
	        jwtDecoder.decode(token);
	        logger.info("Valid RSA JWT token.");
	        return true;
	    } catch (Exception e) {
	        logger.error("Invalid RSA JWT token: {}", e.getMessage());
	        return false;
	    }
	}

	public String getClaimFromToken(String token, String claim) {
		try {
			JwtDecoder decoder = getJwtDecoder();
			org.springframework.security.oauth2.jwt.Jwt jwt = decoder.decode(token);
			return jwt.getClaimAsString(claim);
		} catch (Exception e) {
			logger.error("Error extracting claim from Keycloak token: {}", e.getMessage());
			return null;
		}
	}

	public boolean validateJWT(String token) {
		try {
			JwtDecoder jwtDecoder = getJwtDecoder();
			jwtDecoder.decode(token);
			logger.info("KEYCLOAK - Valid RSA JWT token.");
			return true;
		} catch (Exception e) {
			logger.error("Invalid RSA JWT token: {}", e.getMessage());
			return false;
		}
	}

	public String getUserNameFromRSAToken(String token) {
		org.springframework.security.oauth2.jwt.Jwt jwt = getJwtDecoder().decode(token);
		return jwt.getClaim(USERNAME);
	}

	public String getOfficeFromKeycloakToken(String token) {
		try {
			org.springframework.security.oauth2.jwt.Jwt jwt = getJwtDecoder().decode(token);
			String office = jwt.getClaimAsString(OFFICE);
			logger.debug("Extracted 'office' field from Keycloak token: {}", office);
			return office;
		} catch (Exception e) {
			logger.error("Error extracting office from Keycloak token: {}", e.getMessage());
			return null;
		}
	}

	public List<GrantedAuthority> getRolesFromKeycloakToken(String token) {
		try {
			org.springframework.security.oauth2.jwt.Jwt jwt = getJwtDecoder().decode(token);

			Map<String, Object> realmAccess = jwt.getClaim(REALM_ACCESS);
			List<String> roles = (List<String>) realmAccess.get(ROLES);

			List<GrantedAuthority> authorities = roles.stream().map(SimpleGrantedAuthority::new)
					.collect(Collectors.toList());

			logger.debug("Keycloak Authorities from token: {}", authorities);
			return authorities;
		} catch (Exception e) {
			logger.error("Error extracting roles from Keycloak token: {}", e.getMessage());
			return Collections.emptyList();
		}
	}
}

