@Component
public class RolesMapper {
	
	private final Logger logger = LoggerFactory.getLogger(this.getClass());
	
	@Autowired
	Environment env; 
	
	public List<GrantedAuthority> getRoles(Set<String> groupMemberships){
		logger.info("ALL ROLES by User: {}", groupMemberships.toString());
		String appRoles = env.getProperty("customs.app-roles");
		String ITRole = null;
        Set<String> appRolesSet = new HashSet<String>( Arrays.asList(appRoles.split(", ")));
        for (String appRole : appRolesSet) {
			if (appRole.contains("|IT")) {
				ITRole = appRole.replace("|IT", "");
			}
		}
        if (ITRole != null) {
        	appRolesSet.clear();
        	appRolesSet.add(ITRole);
		}
        Set<String> userRolesSet = new HashSet<>(groupMemberships);
        userRolesSet.retainAll(appRolesSet);
		List<GrantedAuthority> authorities = new ArrayList<>();
		for (String role: userRolesSet) {
			 authorities.add(new SimpleGrantedAuthority(role));
			}
		logger.info("ROLES in APP loaded");
		return authorities;
		

}
	
}

