@Component
public class JwtUtils {
	private static final Logger logger = LoggerFactory.getLogger(JwtUtils.class);

	
	private static String KEYCLOAK = "KEYCLOAK";
	private static String USERNAME = "username";
	private static String ROLES = "roles";
	private static String DEPARTMENT = "department";
	private static String SUBJECT = "subject";

	@Value("${customs.jwt.secret}")
	private String jwtSecret;

	@Value("${customs.jwt.expiration-ms}")
	private int jwtExpirationMs;

	@Value("${customs.auth-mode}")
	private String authMode;

	@Value("${spring.security.oauth2.resourceserver.jwt.issuer-uri}")
	private String issuerUri;

	@Autowired
	Environment env;

	@Autowired
	private AppConfig appConfig;

	@Autowired
	KeycloakService keycloakService;

	@Autowired
	HmacJwtService hmacJwtService;

	@Autowired
	CibEmployeesRepository cibEmployeesRepository;

	public String generateJwtToken(Authentication authentication) {

		return Jwts.builder().setSubject((authentication.getName()))
				.claim(ROLES, authentication.getAuthorities().toString().replaceAll("\\bROLE_", ""))
				.claim(USERNAME, authentication.getName())
				.claim(DEPARTMENT, appConfig.getUserDepartment().getDepartment().toString()).setIssuedAt(new Date())
				.setExpiration(new Date((new Date()).getTime() + jwtExpirationMs))
				.signWith(key(), SignatureAlgorithm.HS256).compact();
	}

	public boolean validateJwtToken(String token) {
		if (KEYCLOAK.equalsIgnoreCase(authMode)) {
			return keycloakService.validateJWT(token);
		} else {
			return hmacJwtService.validateJWT(token);
		}
	}

	public String getUserNameFromJwtToken(String token) {
		if (KEYCLOAK.equalsIgnoreCase(authMode)) {
			return keycloakService.getUserNameFromRSAToken(token);
		} else {
			return hmacJwtService.getClaimFromToken(token, USERNAME);
			// Jwts.parserBuilder().setSigningKey(hmacKey()).build().parseClaimsJws(token).getBody().getSubject();
		}
	}

	public String getDepartmentFromJwtToken(String token) {
		if (KEYCLOAK.equalsIgnoreCase(authMode)) {
			// Privremeno za imijajlovic, sdejanovic
			//Ovo je samo da u toku razvoja mogu da podisimn fiktivne brancheve IGOR, STEVA BORISAV
			String branch;
			if (getUserNameFromJwtToken(token).equals("borpopovic")) {
				branch = "International";
			}
			else if (getUserNameFromJwtToken(token).equals("imijajlovic") ) {
	        	   branch = "KRUS";
//				branch = "BBC";
//				branch = "International";
//				branch = "Mid Corporates";
			}
			else if (getUserNameFromJwtToken(token).equals("bopuzovic") ) {
				branch = "KRUS";
//				branch = "International";
			}
			else if (getUserNameFromJwtToken(token).equals("sbubanja") ) {
				branch = "KRUS";
//				branch = "International";
			}
			else if (getUserNameFromJwtToken(token).equals("sdejanovic") ) {
				branch = "LESK";
			}else if (getUserNameFromJwtToken(token).equals("apolic") ) {
				branch = "KRAG";
			}
			else if (getUserNameFromJwtToken(token).equals("kcvetkovic") ) {
				branch = "International";
			}
			else if (getUserNameFromJwtToken(token).equals("jpadezanin") ) {
				branch = "Region East/West/South";
			}
			else if (getUserNameFromJwtToken(token).equals("kcvetkovic") ) {
				branch = "International";
			}
			else if (getUserNameFromJwtToken(token).equals("jpadezanin") ) {
				branch = "Region East/West/South";
			}
			else {
				branch = keycloakService.getOfficeFromKeycloakToken(token);
			}
			return branch;
			// end
			// return keycloakService.getOfficeFromKeycloakToken(token);
		} else {
			return hmacJwtService.getClaimFromToken(token, DEPARTMENT);
		}
	}

	public String getDepartmentFromJwtTokenCIB(String token) {
		if (KEYCLOAK.equalsIgnoreCase(authMode)) {

			String username =  getUserNameFromJwtToken(token);

			CibEmployee cibEmployee = cibEmployeesRepository.findByUsername(username);
			// Ako departmentNew postoji, koristi njega, inaŽ?e koristi department
			String cibDepartment = cibEmployee.getDepartmentNew() != null
					? cibEmployee.getDepartmentNew()
					: cibEmployee.getDepartment();

			logger.debug("getDepartmentFromJwtTokenCIB CIB department: {}", cibDepartment);
			return cibDepartment;
		} else {
			return hmacJwtService.getClaimFromToken(token, DEPARTMENT);
		}
	}

	public List<GrantedAuthority> getRolesFromJwtToken(String token) {
		if (KEYCLOAK.equalsIgnoreCase(authMode)) {
			return keycloakService.getRolesFromKeycloakToken(token);
		} else {
			return hmacJwtService.getRolesFromHMACToken(token);
		}
	}

	private Key key() {
		return Keys.hmacShaKeyFor(Decoders.BASE64.decode(jwtSecret));
	}
}

